final class Orion_Intent_Classifier{
 public function classify(string $message,array $history,array $state,array $settings):array{$provider=Orion_AI_Provider_Factory::create($settings);$fallback=$this->fallback();$system='You are a semantic router for a WooCommerce shopping assistant. Understand meaning, paraphrases and conversation context. Call route_request exactly once. Treat short messages as answers to saved_state.pending_clarifications when those exist. Preserve the active project for such answers; do not classify them as a new topic or manager follow-up. Ask at most three questions and only when missing information materially changes suitability, safety or quantity. Never calculate area_m2 until the dimension unit is known. Store numeric dimensions separately in dimension_length and dimension_width, and dimension_unit as m or ft. For store policy requests, use policy_query and do not create a product search plan. For product/project requests create role-based searches. Use manager_follow_up only when meaning cannot safely be determined from the message, history and pending questions.';$tool=array('type'=>'function','function'=>array('name'=>'route_request','description'=>'Return the semantic route.','parameters'=>array('type'=>'object','additionalProperties'=>false,'properties'=>array('intent'=>array('type'=>'string','enum'=>array('project_recommendation','product_search','store_policy','general','manager_follow_up')),'topic'=>array('type'=>'string'),'is_new_topic'=>array('type'=>'boolean'),'confidence'=>array('type'=>'number'),'needs_clarification'=>array('type'=>'boolean'),'clarifying_questions'=>array('type'=>'array','items'=>array('type'=>'string'),'maxItems'=>3),'policy_query'=>array('type'=>'string'),'state_patch'=>array('type'=>'object','properties'=>array('project_type'=>array('type'=>'string'),'surface'=>array('type'=>'string'),'area_m2'=>array('type'=>'number'),'environment'=>array('type'=>'string'),'traffic'=>array('type'=>'string'),'colour'=>array('type'=>'string'),'finish'=>array('type'=>'string'),'dimensions'=>array('type'=>'string'),'dimension_length'=>array('type'=>'number'),'dimension_width'=>array('type'=>'number'),'dimension_unit'=>array('type'=>'string'),'notes'=>array('type'=>'string'))),'search_plan'=>array('type'=>'array','maxItems'=>10,'items'=>array('type'=>'object','properties'=>array('role'=>array('type'=>'string'),'query'=>array('type'=>'string'),'required'=>array('type'=>'boolean'),'requirements'=>array('type'=>'object')),'required'=>array('role','query','required')))),'required'=>array('intent','topic','is_new_topic','confidence','needs_clarification','clarifying_questions','policy_query','state_patch','search_plan'))));$context=array('saved_state'=>$state,'recent_messages'=>array_slice($history,-8),'current_message'=>$message);$result=$provider->chat(array(array('role'=>'system','content'=>$system),array('role'=>'user','content'=>wp_json_encode($context))),array($tool));if(empty($result['ok'])){$fallback['_diagnostic']=array('status'=>'provider_error','error'=>sanitize_text_field((string)($result['error']??'Unknown provider error')));return$fallback;}$data=null;$calls=$result['message']['tool_calls']??array();if($calls)$data=json_decode((string)($calls[0]['function']['arguments']??'{}'),true);if(!is_array($data))$data=$this->decode((string)($result['message']['content']??''));if(!is_array($data)){$fallback['_diagnostic']=array('status'=>'invalid_output','tool_calls'=>count($calls),'content_excerpt'=>mb_substr(sanitize_textarea_field((string)($result['message']['content']??'')),0,500));return$fallback;}$out=$this->validate($data,$fallback);$out['_diagnostic']=array('status'=>'ok','usage'=>$result['usage']??array());return$out;}
 private function fallback():array{return array('intent'=>'manager_follow_up','topic'=>'unclassified','is_new_topic'=>false,'confidence'=>0.0,'needs_clarification'=>false,'clarifying_questions'=>array(),'policy_query'=>'','state_patch'=>array(),'search_plan'=>array(),'_diagnostic'=>array('status'=>'fallback'));}
 private function validate(array $data,array $out):array{$allowed=array('project_recommendation','product_search','store_policy','general','manager_follow_up');$out['intent']=in_array($data['intent']??'',$allowed,true)?$data['intent']:'manager_follow_up';$out['topic']=sanitize_key((string)($data['topic']??''));$out['is_new_topic']=!empty($data['is_new_topic']);$out['confidence']=max(0,min(1,(float)($data['confidence']??0)));$out['needs_clarification']=!empty($data['needs_clarification']);$out['policy_query']=sanitize_text_field((string)($data['policy_query']??''));$questions=is_array($data['clarifying_questions']??null)?$data['clarifying_questions']:array();$out['clarifying_questions']=array_slice(array_values(array_filter(array_map(static fn($v)=>sanitize_text_field((string)$v),$questions))),0,3);$allowed_state=array('project_type','surface','area_m2','environment','traffic','colour','finish','dimensions','dimension_length','dimension_width','dimension_unit','notes');$patch=is_array($data['state_patch']??null)?$data['state_patch']:array();foreach($allowed_state as$key)if(array_key_exists($key,$patch)&&$patch[$key]!==''&&$patch[$key]!==null)$out['state_patch'][$key]=is_numeric($patch[$key])?(float)$patch[$key]:sanitize_text_field((string)$patch[$key]);if((isset($out['state_patch']['dimension_length'])||isset($out['state_patch']['dimension_width']))&&empty($out['state_patch']['dimension_unit']))unset($out['state_patch']['area_m2']);$plan=is_array($data['search_plan']??null)?$data['search_plan']:array();foreach(array_slice($plan,0,10)as$item){if(!is_array($item))continue;$role=sanitize_key((string)($item['role']??''));$query=sanitize_text_field((string)($item['query']??''));if(!$role||!$query)continue;$requirements=is_array($item['requirements']??null)?$item['requirements']:array();$clean=array();foreach(array_slice($requirements,0,10,true)as$k=>$v)$clean[sanitize_key((string)$k)]=sanitize_text_field(is_scalar($v)?(string)$v:wp_json_encode($v));$out['search_plan'][]=array('role'=>$role,'query'=>$query,'required'=>!empty($item['required']),'requirements'=>$clean);}return$out;}
 private function decode(string $text):?array{$text=trim(preg_replace('/^```(?:json)?\s*|\s*```$/i','',trim($text)));$data=json_decode($text,true);if(is_array($data))return$data;if(preg_match('/\{[\s\S]*\}/',$text,$m)){$data=json_decode($m[0],true);return is_array($data)?$data:null;}return null;}
}
